-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.evoker.augmentation.Name"] = "Icy Veins"
L["rm.retail.evoker.augmentation.Description"] = "Empfohlen für Verstärkung: die Schwarzmacht-Priorität von Icy Veins. Schwarzmacht ist einer der wenigen Stärkungszauber, die das Spiel Addons im Kampf in Midnight noch anzeigt, daher funktioniert ihre Aufrechterhaltung dort. Außerhalb des Kampfes: Sengende Schuppen auf ein freundliches Gruppenziel ohne sie, Lebende Flamme auf einen Gegner. Dann Schwarzmacht, wenn sie fehlt oder unter 4 Sekunden liegt, und bei Abklingzeit-Ende, sofern Atem der Äonen nicht bereit ist; Voraussicht; Feueratem; Emporstoßen; Eruption während Schwarzmacht oder mit zwei Stapeln Essenzexplosion; Azurstoß; Lebende Flamme. Verborgene Stärkungszauber überspringen im Kampf nur ihren eigenen Schritt. Erinnerungen: Atem der Äonen und Tiefer Atem (Sie zielen selbst), Zeitdruck mit bereitem Feueratem, Zeitsprung, wenn Feueratem und Emporstoßen beide abklingen, dazu die Erinnerungen an Hilfsfähigkeiten. Voraussicht und Sengende Schuppen gehen auf Ihr Ziel: Die Wahl des Verbündeten und der Ermächtigungsstufe liegt bei Ihnen."
L["rm.retail.evoker.augmentation.assisted.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.evoker.augmentation.assisted.Description"] = "Vorschlag von Blizzards Kampfassistent für Verstärkung, eine Alternative zur empfohlenen integrierten Verstärkungsrotation nach Icy Veins, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Sie wirkt Schwarzmacht erst neu, nachdem sie ausgelaufen ist, und wartet, während Sie wirken oder einen ermächtigten Zauber halten. Erinnerungen im Kampf an Atem der Äonen, Tiefer Atem, Zeitdruck und Zeitsprung, dazu Unterdrücken, Obsidianschuppen, Segen der Bronzenen und Quell der Magie wie in den anderen integrierten Rufer-Rotationen."
L["rm.retail.evoker.devastation.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.evoker.devastation.Description"] = "Empfohlen für Verheerung. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken, Desintegration kanalisieren oder einen ermächtigten Zauber halten. Die Wahl der Ermächtigungsstufe liegt bei Ihnen. Daneben Erinnerungen im Kampf an Drachenwut, Tiefer Atem und Zeitdruck, Unterdrücken bei einem unterbrechbaren Zauber und Obsidianschuppen, wann immer sie bereit sind, sowie außerhalb des Kampfes an Segen der Bronzenen, wenn er fehlt, und Quell der Magie auf einem freundlichen Ziel in Ihrer Gruppe. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet Unterdrücken nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Obsidianschuppen Ihnen überlassen."
L["rm.retail.evoker.devastation.guide.Name"] = "Referenz (SimulationCraft und Icy Veins)"
L["rm.retail.evoker.devastation.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die optimale Priorität für Verheerung. Procs, Abklingzeiten und der Brand auf dem Ziel sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; lesen Sie sie, oder duplizieren Sie sie, um damit zu experimentieren. Zieht mit Lebender Flamme. Schuppenkommandant (Massendesintegration erlernt): Ewigkeitswoge, Feueratem, Tiefer Atem gegen zwei oder mehr Gegner, Desintegration mit Aufladungen von Massendesintegration, Scheiterhaufen gegen fünf oder mehr, Desintegration, Lebende Flamme bei Feurigem Schub mit Springenden Flammen, Ungebundene Flamme unter zwei Stapeln Essenzexplosion, Azurfeger. Flammenformer: Ewigkeitswoge, Feueratem, wenn sein Brand fehlt oder ausläuft, Scheiterhaufen gegen fünf oder mehr, Desintegration, Tiefer Atem gegen vier oder mehr, Ungebundene Flamme, Lebende Flamme bei Feurigem Schub mit Springenden Flammen, Azurfeger. Dann Azurstoß in Bewegung, Lebende Flamme, Azurstoß. Setzen Sie ermächtigte Zauber gegen ein Ziel auf Stufe 1 ein (Icy Veins). Erinnerungen: Drachenwut, Zeitdruck während Drachenwut oder mit bereitem Feueratem, Tiefer Atem für Schuppenkommandant, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.evoker.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.evoker.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Rufers meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Rufer-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.evoker.preservation.Name"] = "Referenz (Icy Veins)"
L["rm.retail.evoker.preservation.Description"] = "Nur als Referenz, standardmäßig deaktiviert. Die Gesundheit von Verbündeten, Echo, Umkehrung, Essenzexplosion und jede Abklingzeit sind im Kampf in Midnight für Addons verborgen, Rotation Master kann nicht wählen, wen Sie heilen, und Blizzard hat keine Kampfassistent-Rotation für Heiler, daher heilt diese integrierte Rotation nicht. Sie erinnert außerhalb des Kampfes an Segen der Bronzenen und Quell der Magie, und wenn Ihr Ziel ein Gegner ist, schlägt sie Schaden vor: Feueratem, Desintegration, Lebende Flamme und Azurstoß in Bewegung. Erinnerungen an Unterdrücken und Obsidianschuppen wie in den anderen integrierten Rufer-Rotationen. Das Heilen bleibt Ihnen überlassen."
